"use client"

import { Badge } from "@/patina/ui/badge"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/patina/ui/card"
import { Progress } from "@/patina/ui/progress"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/patina/ui/table"

// The dashboard's lists, usable on their own: a ledger of records with a stamped status, and a survey under way as
// progress over its sectors.

/** A count in a fixed locale, so the server and every browser print the same digits. */
export const tally = (n: number) => new Intl.NumberFormat("en-GB").format(n)

export type RecordStatus = "confirmed" | "unconfirmed" | "rare"

const STATUS: Record<
  RecordStatus,
  { label: string; badge: "secondary" | "outline" | "default" }
> = {
  confirmed: { label: "Confirmed", badge: "secondary" },
  unconfirmed: { label: "Unconfirmed", badge: "outline" },
  rare: { label: "Rare", badge: "default" },
}

export interface RecordsCardProps {
  title: string
  description: string
  rows: {
    id: string
    species: string
    place: string
    status: RecordStatus
    count: number
    /** A page for the record; its species links there. */
    href?: string
  }[]
}

/** A ledger of records; the place column goes when the card is too narrow for it. */
export function RecordsCard({ title, description, rows }: RecordsCardProps) {
  return (
    <Card className="@container/records">
      <CardHeader>
        <CardTitle>{title}</CardTitle>
        <CardDescription>{description}</CardDescription>
      </CardHeader>
      <CardContent>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Species</TableHead>
              <TableHead className="@max-[30rem]/records:hidden">
                Place
              </TableHead>
              <TableHead>Status</TableHead>
              <TableHead className="text-right">Count</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {rows.map((row) => (
              <TableRow key={row.id}>
                <TableCell>
                  {row.href ? (
                    <a href={row.href}>{row.species}</a>
                  ) : (
                    row.species
                  )}
                </TableCell>
                <TableCell className="text-ink-2 @max-[30rem]/records:hidden">
                  {row.place}
                </TableCell>
                <TableCell>
                  <Badge variant={STATUS[row.status].badge}>
                    {STATUS[row.status].label}
                  </Badge>
                </TableCell>
                <TableCell className="text-right tabular-nums">
                  {tally(row.count)}
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </CardContent>
    </Card>
  )
}

export interface SurveyCardProps {
  title: string
  description: string
  sectors: { name: string; counted: boolean }[]
}

/** A survey under way: the share of sectors done as progress, then each sector and whether it is counted. */
export function SurveyCard({ title, description, sectors }: SurveyCardProps) {
  const done = sectors.filter((s) => s.counted).length
  return (
    <Card className="self-start">
      <CardHeader>
        <CardTitle>{title}</CardTitle>
        <CardDescription>{description}</CardDescription>
      </CardHeader>
      <CardContent>
        <Progress
          value={(done / Math.max(1, sectors.length)) * 100}
          aria-label="Sectors counted"
        />
        <p className="label-mono m-0 mt-tight text-ink-2">
          {done} of {sectors.length} sectors counted
        </p>
        <ul className="m-0 mt-snug list-none p-0">
          {sectors.map((sector) => (
            <li
              key={sector.name}
              className="flex items-baseline justify-between gap-tight border-b border-dashed border-rule py-hair"
            >
              <span className={sector.counted ? "" : "text-ink-2"}>
                {sector.name}
              </span>
              <span className="label-mono text-ink-3">
                {sector.counted ? "Counted" : "To do"}
              </span>
            </li>
          ))}
        </ul>
      </CardContent>
    </Card>
  )
}

"use client"

import type { ReactNode } from "react"
import { Bar, BarChart, CartesianGrid, LabelList, XAxis, YAxis } from "recharts"
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/patina/ui/card"
import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  drawnBar,
  type ChartConfig,
} from "@/patina/ui/chart"

// The dashboard's parts, usable on their own: a headline number, a card that frames a chart, and its two charts in
// drawn bars over per-series hatch.

/** A headline number: what it counts in mono, the number, one line of context. */
export function StatCard({
  label,
  value,
  note,
}: {
  label: string
  value: string
  note: string
}) {
  return (
    <Card size="sm">
      <CardContent>
        <p className="label-mono m-0 text-ink-2">{label}</p>
        <p className="m-0 mt-hair font-read text-h1 leading-heading tabular-nums">
          {value}
        </p>
        <p className="m-0 mt-hair text-small leading-small text-ink-2">
          {note}
        </p>
      </CardContent>
    </Card>
  )
}

/** A chart with its title and period above and one line on what it shows below. */
export function ChartCard({
  title,
  description,
  footer,
  children,
}: {
  title: string
  description: string
  footer: string
  children: ReactNode
}) {
  return (
    <Card>
      <CardHeader>
        <CardTitle>{title}</CardTitle>
        <CardDescription>{description}</CardDescription>
      </CardHeader>
      <CardContent>{children}</CardContent>
      <CardFooter>
        <p className="m-0 text-small leading-small text-ink-2">{footer}</p>
      </CardFooter>
    </Card>
  )
}

const dailyConfig = {
  observations: { label: "Observations" },
} satisfies ChartConfig
const placeConfig = { birds: { label: "Birds counted" } } satisfies ChartConfig

/** Records per day as drawn bars in hatch; the axis shows the date, the tooltip the weekday too ("Sat 14"). */
export function DailyChart({
  data,
}: {
  data: { day: string; observations: number }[]
}) {
  return (
    <ChartContainer config={dailyConfig} className="aspect-auto h-56 w-full">
      <BarChart
        accessibilityLayer
        data={data}
        margin={{ top: 8, right: 4, bottom: 0, left: 0 }}
      >
        <CartesianGrid vertical={false} />
        <XAxis
          dataKey="day"
          tickLine={false}
          tickMargin={8}
          tickFormatter={(d: string) => d.split(" ")[1] ?? d}
        />
        <YAxis
          tickLine={false}
          axisLine={false}
          width={28}
          allowDecimals={false}
        />
        <ChartTooltip content={<ChartTooltipContent />} />
        <Bar
          dataKey="observations"
          fill="var(--hatch-observations)"
          shape={drawnBar}
        />
      </BarChart>
    </ChartContainer>
  )
}

/** A count per place as horizontal drawn bars, most first, each labelled with its number. */
export function PlaceChart({
  data,
}: {
  data: { place: string; birds: number }[]
}) {
  return (
    <ChartContainer config={placeConfig} className="aspect-auto h-56 w-full">
      <BarChart
        accessibilityLayer
        data={data}
        layout="vertical"
        margin={{ top: 0, right: 40, bottom: 0, left: 0 }}
      >
        <XAxis type="number" hide />
        <YAxis
          type="category"
          dataKey="place"
          tickLine={false}
          axisLine={false}
          width={100}
        />
        <ChartTooltip content={<ChartTooltipContent />} />
        <Bar dataKey="birds" fill="var(--hatch-birds)" shape={drawnBar}>
          <LabelList
            dataKey="birds"
            position="right"
            className="fill-ink-2 font-label text-label tabular-nums"
          />
        </Bar>
      </BarChart>
    </ChartContainer>
  )
}

"use client"

import { cn } from "@/patina/lib/utils"
import {
  RecordsCard,
  SurveyCard,
  tally,
  type RecordsCardProps,
  type SurveyCardProps,
} from "@/patina/blocks/dashboard-01-lists"
import {
  ChartCard,
  DailyChart,
  PlaceChart,
  StatCard,
} from "@/patina/blocks/dashboard-01-parts"

// A week at a glance: four headline numbers, records per day and counts per place as drawn bars in hatch, a ledger
// of records and a survey's progress. Pass your own data, shaped like SAMPLE; the layout follows the width of its
// container, so it works beside a sidebar as well as on a whole page.

export const meta = {
  title: "Dashboard",
  description:
    "A week at a glance: headline numbers, two hand-drawn bar charts in hatch, a ledger of records and a survey in progress.",
}

export interface Dashboard01Data {
  /** The place the numbers describe, above the title. */
  site: string
  /** The period, beside the site and under the charts' titles. */
  week: string
  stats: { label: string; value: number; note: string }[]
  daily: { day: string; observations: number }[]
  dailyNote: string
  places: { place: string; birds: number }[]
  placesNote: string
  records: RecordsCardProps
  survey: SurveyCardProps
}

/** A saltmarsh reserve in the week of Sun 8 – Sat 14 Nov 2026. */
export const SAMPLE: Dashboard01Data = {
  site: "Saltmarsh reserve",
  week: "Sun 8 – Sat 14 Nov",
  stats: [
    { label: "Observations", value: 12, note: "Most on Thu 12" },
    { label: "Species", value: 12, note: "One record each" },
    { label: "Rare", value: 3, note: "For the county report" },
    { label: "Birds counted", value: 352, note: "79% on the tidal flats" },
  ],
  daily: [
    { day: "Sun 8", observations: 0 },
    { day: "Mon 9", observations: 0 },
    { day: "Tue 10", observations: 2 },
    { day: "Wed 11", observations: 2 },
    { day: "Thu 12", observations: 3 },
    { day: "Fri 13", observations: 3 },
    { day: "Sat 14", observations: 2 },
  ],
  dailyNote: "Nothing on Sunday or Monday; the most on Thu 12.",
  places: [
    { place: "Tidal flats", birds: 279 },
    { place: "Saltings", birds: 61 },
    { place: "Sea wall", birds: 6 },
    { place: "Reed bed", birds: 3 },
    { place: "North hide", birds: 2 },
    { place: "Sluice gate", birds: 1 },
  ],
  placesNote:
    "The tidal flats carry 79% of the birds, most of them one goose flock.",
  records: {
    title: "Recent records",
    description: "The week's latest six",
    rows: [
      {
        id: "obs-0412",
        species: "Grey heron",
        place: "Tidal flats",
        status: "confirmed",
        count: 1,
      },
      {
        id: "obs-0411",
        species: "Curlew",
        place: "Saltings",
        status: "confirmed",
        count: 14,
      },
      {
        id: "obs-0410",
        species: "Bittern",
        place: "Reed bed",
        status: "rare",
        count: 1,
      },
      {
        id: "obs-0409",
        species: "Brent goose",
        place: "Tidal flats",
        status: "confirmed",
        count: 230,
      },
      {
        id: "obs-0408",
        species: "Kingfisher",
        place: "Sluice gate",
        status: "unconfirmed",
        count: 1,
      },
      {
        id: "obs-0407",
        species: "Avocet",
        place: "Saltings",
        status: "confirmed",
        count: 36,
      },
    ],
  },
  survey: {
    title: "Winter wader count",
    description: "Today · led by Mira Okafor",
    sectors: [
      { name: "Tidal flats north", counted: true },
      { name: "Tidal flats south", counted: true },
      { name: "Saltings", counted: true },
      { name: "Sluice gate", counted: true },
      { name: "Sea wall", counted: false },
      { name: "North hide", counted: false },
    ],
  },
}

export interface Dashboard01Props {
  data?: Dashboard01Data
  title?: string
  className?: string
}

export function Dashboard01({
  data = SAMPLE,
  title = "Overview",
  className,
}: Dashboard01Props) {
  return (
    <div className={cn("@container", className)}>
      <div className="mx-auto max-w-[72rem] px-snug pt-section pb-page @min-[40rem]:px-line">
        <p className="label-mono m-0 text-ink-2">
          {data.site} · {data.week}
        </p>
        <h1 className="m-0 mt-hair text-h1">{title}</h1>

        <section
          aria-label="This week"
          className="mt-line grid grid-cols-2 gap-snug @min-[56rem]:grid-cols-4"
        >
          {data.stats.map((stat) => (
            <StatCard
              key={stat.label}
              label={stat.label}
              value={tally(stat.value)}
              note={stat.note}
            />
          ))}
        </section>

        <div className="mt-snug grid gap-snug @min-[56rem]:grid-cols-2">
          <ChartCard
            title="Observations per day"
            description={data.week}
            footer={data.dailyNote}
          >
            <DailyChart data={data.daily} />
          </ChartCard>
          <ChartCard
            title="Birds counted by place"
            description="Same week, every species"
            footer={data.placesNote}
          >
            <PlaceChart data={data.places} />
          </ChartCard>
        </div>

        <div className="mt-snug grid gap-snug @min-[56rem]:grid-cols-[minmax(0,1fr)_20rem]">
          <RecordsCard {...data.records} />
          <SurveyCard {...data.survey} />
        </div>
      </div>
    </div>
  )
}

export default Dashboard01
